-----------------------------------------------------------------------------------------
-- uart transmit module
--
-- Local change (see ORIGIN.md): optional parity bit and second stop bit, chosen by
-- cfgParityEn, cfgParityOdd and cfgStop2. With the three at '0' (the default) the frame is
-- the 8N1 of the upstream module, bit for bit.
-----------------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity uartTx is
  port ( clr       : in  std_logic;                    -- global reset input
         clk       : in  std_logic;                    -- global clock input
         ce16      : in  std_logic;                    -- baud rate multiplyed by 16 - generated by baud module
         txData    : in  std_logic_vector(7 downto 0); -- data byte to transmit
         newTxData : in  std_logic;                    -- asserted to indicate that there is a new data byte for transmission
         cfgParityEn  : in std_logic := '0';           -- '1' sends a parity bit after the data bits
         cfgParityOdd : in std_logic := '0';           -- '1' odd parity, '0' even parity (when cfgParityEn is '1')
         cfgStop2     : in std_logic := '0';           -- '1' sends two stop bits
         serOut    : out std_logic;                    -- serial data output
         txBusy    : out std_logic);                   -- signs that transmitter is busy
end uartTx;

architecture Behavioral of uartTx is

  signal iTxBusy  : std_logic;
  signal ce1      : std_logic; -- clock enable at bit rate
  signal count16  : std_logic_vector(3 downto 0);
  signal bitCount : std_logic_vector(3 downto 0);
  signal dataBuf  : std_logic_vector(9 downto 0);
  signal lastBit  : std_logic_vector(3 downto 0); -- value of bitCount in the last bit of the frame
  signal parityBit : std_logic;                   -- parity of the byte, or '1' (a stop level) without parity

  begin
    parityBit <= (xor txData) xor cfgParityOdd when cfgParityEn = '1' else '1';
    -- a counter to count 16 pulses of ce_16 to generate the ce_1 pulse
    process (clr, clk)
    begin
      if (clr = '1') then
        count16 <= (others => '0');
      elsif (rising_edge(clk)) then
        if ((iTxBusy = '1') and (ce16 = '1')) then
          count16 <= std_logic_vector(unsigned(count16) + 1);
        elsif (iTxBusy = '0') then
          count16 <= (others => '0');
        end if;
      end if;
    end process;
    -- tx_busy flag
    process (clr, clk)
    begin
      if (clr = '1') then
        iTxBusy <= '0';
      elsif (rising_edge(clk)) then
        if ((iTxBusy = '0') and (newTxData = '1')) then
          iTxBusy <= '1';
        elsif ((iTxBusy = '1') and (bitCount = lastBit) and (ce1 = '1')) then
          iTxBusy <= '0';
        end if;
      end if;
    end process;
    -- frame length, captured while idle: start, 8 data, parity (optional), 1 or 2 stop bits
    process (clr, clk)
    begin
      if (clr = '1') then
        lastBit <= "1001";
      elsif (rising_edge(clk)) then
        if (iTxBusy = '0') then
          if (cfgParityEn = '1' and cfgStop2 = '1') then
            lastBit <= "1011";
          elsif (cfgParityEn = '1' or cfgStop2 = '1') then
            lastBit <= "1010";
          else
            lastBit <= "1001";
          end if;
        end if;
      end if;
    end process;
    -- output bit counter
    process (clr, clk)
    begin
      if (clr = '1') then
        bitCount <= (others => '0');
      elsif (rising_edge(clk)) then
        if ((iTxBusy = '1') and (ce1 = '1')) then
          bitCount <= std_logic_vector(unsigned(bitCount) + 1);
        elsif (iTxBusy = '0') then
          bitCount <= (others => '0');
        end if;
      end if;
    end process;
    -- data shift register
    process (clr, clk)
    begin
      if (clr = '1') then
        dataBuf <= (others => '0');
      elsif (rising_edge(clk)) then
        if (iTxBusy = '0') then
          dataBuf <= parityBit & txData & '0';
        elsif ((iTxBusy = '1') and (ce1 = '1')) then
          dataBuf <= '1' & dataBuf(9 downto 1);
        end if;
      end if;
    end process;
    -- output data bit
    process (clr, clk)
    begin
      if (clr = '1') then
        serOut <= '1';
      elsif (rising_edge(clk)) then
        if (iTxBusy = '1') then
          serOut <= dataBuf(0);
        else
          serOut <= '1';
        end if;
      end if;
    end process;
    -- ce_1 pulse indicating output data bit should be updated
    ce1 <= '1' when ((count16 = "1111") and (ce16 = '1')) else '0';
    txBusy <= iTxBusy;
  end Behavioral;
